# test_property_based.py
import pytest
from hypothesis import given, strategies as st, settings
from hypothesis.stateful import RuleBasedStateMachine, rule, Bundle
import threading
import asyncio

# pip install hypothesis

class Counter:
    def __init__(self):
        self.value = 0
        self.lock = threading.Lock()

    def increment(self):
        with self.lock:
            self.value += 1

    def decrement(self):
        with self.lock:
            self.value -= 1

    def get(self):
        return self.value

class CounterStateMachine(RuleBasedStateMachine):
    """State machine for testing counter"""

    def __init__(self):
        super().__init__()
        self.counter = Counter()
        self.expected = 0

    @rule()
    def increment(self):
        self.counter.increment()
        self.expected += 1

    @rule()
    def decrement(self):
        self.counter.decrement()
        self.expected -= 1

    @rule()
    def check_value(self):
        assert self.counter.get() == self.expected

# Run with: pytest test_property_based.py -v
TestCounter = CounterStateMachine.TestCase

# Property-based test for concurrent operations
@given(st.lists(st.integers(min_value=1, max_value=100), min_size=1, max_size=50))
@settings(max_examples=100)
def test_concurrent_sum(values):
    """Test concurrent sum matches sequential sum"""
    result = []
    lock = threading.Lock()

    def add_value(v):
        with lock:
            result.append(v)

    threads = [threading.Thread(target=add_value, args=(v,)) for v in values]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    assert sum(result) == sum(values)
    assert len(result) == len(values)
